;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

 &lt;h1 id=&#34;🧩-Python-程序打包成-EXE-全面教程&#34;&gt;&lt;a href=&#34;#🧩-Python-程序打包成-EXE-全面教程&#34; class=&#34;headerlink&#34; title=&#34;🧩 Python 程序打包成 EXE 全面教程&#34;&gt;&lt;/a&gt;🧩 Python 程序打包成 EXE 全面教程&lt;/h1&gt;&lt;hr&gt;
&lt;h2 id=&#34;📖-一、PyInstaller-简介&#34;&gt;&lt;a href=&#34;#📖-一、PyInstaller-简介&#34; class=&#34;headerlink&#34; title=&#34;📖 一、PyInstaller 简介&#34;&gt;&lt;/a&gt;📖 一、PyInstaller 简介&lt;/h2&gt;&lt;p&gt;&lt;strong&gt;PyInstaller&lt;/strong&gt; 是最常用的 Python 程序打包工具，可以将 &lt;code&gt;.py&lt;/code&gt; 文件及其所有依赖打包成一个可在 Windows 上独立运行的 &lt;code&gt;.exe&lt;/code&gt; 文件。&lt;/p&gt;
&lt;p&gt;特点：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;支持所有主流 Python 版本（3.7+）&lt;/li&gt;
&lt;li&gt;无需安装 Python 即可运行打包后的程序&lt;/li&gt;
&lt;li&gt;可打包为单个文件或文件夹结构&lt;/li&gt;
&lt;li&gt;支持添加图标、资源文件、隐藏命令行窗口等&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;⚙️-二、环境准备&#34;&gt;&lt;a href=&#34;#⚙️-二、环境准备&#34; class=&#34;headerlink&#34; title=&#34;⚙️ 二、环境准备&#34;&gt;&lt;/a&gt;⚙️ 二、环境准备&lt;/h2&gt;&lt;h3 id=&#34;1️⃣-检查-Python-环境&#34;&gt;&lt;a href=&#34;#1️⃣-检查-Python-环境&#34; class=&#34;headerlink&#34; title=&#34;1️⃣ 检查 Python 环境&#34;&gt;&lt;/a&gt;1️⃣ 检查 Python 环境&lt;/h3&gt;&lt;p&gt;在命令行输入：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;python &lt;span class=&#34;token parameter variable&#34;&gt;--version&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;输出类似：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;Python &lt;span class=&#34;token number&#34;&gt;3.10&lt;/span&gt;.13&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;确保系统能正确识别 Python。&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;2️⃣-安装-PyInstaller&#34;&gt;&lt;a href=&#34;#2️⃣-安装-PyInstaller&#34; class=&#34;headerlink&#34; title=&#34;2️⃣ 安装 PyInstaller&#34;&gt;&lt;/a&gt;2️⃣ 安装 PyInstaller&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; pyinstaller&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;验证安装是否成功：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;--version&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;🧱-三、示例项目结构&#34;&gt;&lt;a href=&#34;#🧱-三、示例项目结构&#34; class=&#34;headerlink&#34; title=&#34;🧱 三、示例项目结构&#34;&gt;&lt;/a&gt;🧱 三、示例项目结构&lt;/h2&gt;&lt;p&gt;假设你的项目如下：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-makefile&#34; data-language=&#34;makefile&#34;&gt;&lt;code class=&#34;language-makefile&#34;&gt;project/
│
├─ main.py              &lt;span class=&#34;token comment&#34;&gt;# 主程序&lt;/span&gt;
├─ config/
│   └─ settings.json    &lt;span class=&#34;token comment&#34;&gt;# 配置文件&lt;/span&gt;
└─ images/
    └─ logo.png         &lt;span class=&#34;token comment&#34;&gt;# 图片资源&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;code&gt;main.py&lt;/code&gt; 示例代码：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; json&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; os&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; sys

&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;resource_path&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    &lt;span class=&#34;token triple-quoted-string string&#34;&gt;&#34;&#34;&#34;获取打包后资源文件的路径&#34;&#34;&#34;&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;token builtin&#34;&gt;hasattr&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;sys&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#39;_MEIPASS&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; os&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;path&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;join&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;sys&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;_MEIPASS&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; os&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;path&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;join&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;os&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;path&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;abspath&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;.&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;main&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    config_path &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; resource_path&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;config/settings.json&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;with&lt;/span&gt; &lt;span class=&#34;token builtin&#34;&gt;open&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;config_path&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;r&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; encoding&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;utf-8&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;as&lt;/span&gt; f&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        data &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; json&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;load&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;f&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;配置文件内容：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; data&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token builtin&#34;&gt;input&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;按回车退出...&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; __name__ &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;__main__&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    main&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;🚀-四、打包命令详解&#34;&gt;&lt;a href=&#34;#🚀-四、打包命令详解&#34; class=&#34;headerlink&#34; title=&#34;🚀 四、打包命令详解&#34;&gt;&lt;/a&gt;🚀 四、打包命令详解&lt;/h2&gt;&lt;h3 id=&#34;🔹-最简单的打包&#34;&gt;&lt;a href=&#34;#🔹-最简单的打包&#34; class=&#34;headerlink&#34; title=&#34;🔹 最简单的打包&#34;&gt;&lt;/a&gt;🔹 最简单的打包&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;输出目录结构：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;build/      &lt;span class=&#34;token comment&#34;&gt;# 中间构建文件&lt;/span&gt;
dist/       &lt;span class=&#34;token comment&#34;&gt;# 最终生成的可执行文件所在目录&lt;/span&gt;
main.spec   &lt;span class=&#34;token comment&#34;&gt;# PyInstaller 配置文件&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;进入 &lt;code&gt;dist/main/&lt;/code&gt;，可看到：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;main.exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;🔹-打包成单个-exe-文件&#34;&gt;&lt;a href=&#34;#🔹-打包成单个-exe-文件&#34; class=&#34;headerlink&#34; title=&#34;🔹 打包成单个 .exe 文件&#34;&gt;&lt;/a&gt;🔹 打包成单个 &lt;code&gt;.exe&lt;/code&gt; 文件&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;code&gt;-F&lt;/code&gt; 表示 &lt;strong&gt;onefile&lt;/strong&gt; 模式，将所有依赖打包进单个文件中。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;输出结果：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;dist/main.exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;🔹-添加程序图标&#34;&gt;&lt;a href=&#34;#🔹-添加程序图标&#34; class=&#34;headerlink&#34; title=&#34;🔹 添加程序图标&#34;&gt;&lt;/a&gt;🔹 添加程序图标&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-i&lt;/span&gt; icon.ico main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;blockquote&gt;
&lt;p&gt;图标文件必须是 &lt;code&gt;.ico&lt;/code&gt; 格式（可用在线转换工具把 &lt;code&gt;.png&lt;/code&gt; 转成 &lt;code&gt;.ico&lt;/code&gt;）。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h3 id=&#34;🔹-去除命令行黑框（GUI-程序用）&#34;&gt;&lt;a href=&#34;#🔹-去除命令行黑框（GUI-程序用）&#34; class=&#34;headerlink&#34; title=&#34;🔹 去除命令行黑框（GUI 程序用）&#34;&gt;&lt;/a&gt;🔹 去除命令行黑框（GUI 程序用）&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-w&lt;/span&gt; main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;blockquote&gt;
&lt;p&gt;&lt;code&gt;-w&lt;/code&gt; 或 &lt;code&gt;--windowed&lt;/code&gt; 表示 &lt;strong&gt;隐藏控制台窗口&lt;/strong&gt;。&lt;br&gt; 用于 PyQt5、Tkinter、wxPython 等图形界面应用。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h3 id=&#34;🔹-自定义生成文件名与输出路径&#34;&gt;&lt;a href=&#34;#🔹-自定义生成文件名与输出路径&#34; class=&#34;headerlink&#34; title=&#34;🔹 自定义生成文件名与输出路径&#34;&gt;&lt;/a&gt;🔹 自定义生成文件名与输出路径&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-w&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-i&lt;/span&gt; app.ico &lt;span class=&#34;token parameter variable&#34;&gt;-n&lt;/span&gt; myApp &lt;span class=&#34;token parameter variable&#34;&gt;--distpath&lt;/span&gt; build_output main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;参数说明：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;-n myApp&lt;/code&gt;：自定义可执行文件名。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;--distpath&lt;/code&gt;：指定输出文件夹（默认是 &lt;code&gt;dist&lt;/code&gt;）。&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h3 id=&#34;🔹-打包时包含资源文件&#34;&gt;&lt;a href=&#34;#🔹-打包时包含资源文件&#34; class=&#34;headerlink&#34; title=&#34;🔹 打包时包含资源文件&#34;&gt;&lt;/a&gt;🔹 打包时包含资源文件&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; main.py --add-data &lt;span class=&#34;token string&#34;&gt;&#34;config;config&#34;&lt;/span&gt; --add-data &lt;span class=&#34;token string&#34;&gt;&#34;images;images&#34;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;解释：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;&#34;源路径;目标路径&#34;&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;Windows 用分号 &lt;code&gt;;&lt;/code&gt;，Linux/WSL 用冒号 &lt;code&gt;:&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;打包后：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;dist/main.exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;运行时即可自动包含 &lt;code&gt;config/settings.json&lt;/code&gt; 和 &lt;code&gt;images/logo.png&lt;/code&gt;。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🧩-五、完整打包命令示例&#34;&gt;&lt;a href=&#34;#🧩-五、完整打包命令示例&#34; class=&#34;headerlink&#34; title=&#34;🧩 五、完整打包命令示例&#34;&gt;&lt;/a&gt;🧩 五、完整打包命令示例&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-w&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-i&lt;/span&gt; app.ico &lt;span class=&#34;token parameter variable&#34;&gt;-n&lt;/span&gt; TrafficMonitor ^
--add-data &lt;span class=&#34;token string&#34;&gt;&#34;config;config&#34;&lt;/span&gt; --add-data &lt;span class=&#34;token string&#34;&gt;&#34;images;images&#34;&lt;/span&gt; ^
main.py&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;运行完毕后：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;dist/TrafficMonitor.exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;双击即可运行（无黑框）。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;⚡-六、打包后优化与问题处理&#34;&gt;&lt;a href=&#34;#⚡-六、打包后优化与问题处理&#34; class=&#34;headerlink&#34; title=&#34;⚡ 六、打包后优化与问题处理&#34;&gt;&lt;/a&gt;⚡ 六、打包后优化与问题处理&lt;/h2&gt;&lt;h3 id=&#34;🔸-文件体积太大？&#34;&gt;&lt;a href=&#34;#🔸-文件体积太大？&#34; class=&#34;headerlink&#34; title=&#34;🔸 文件体积太大？&#34;&gt;&lt;/a&gt;🔸 文件体积太大？&lt;/h3&gt;&lt;p&gt;可以用 UPX 压缩：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token comment&#34;&gt;# 安装 UPX（可选）&lt;/span&gt;
pip &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; upx

&lt;span class=&#34;token comment&#34;&gt;# 或手动下载：https://upx.github.io/&lt;/span&gt;
pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; main.py --upx-dir &lt;span class=&#34;token string&#34;&gt;&#34;C:\path&lt;span class=&#34;token entity&#34; title=&#34;\t&#34;&gt;\t&lt;/span&gt;o\upx&#34;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;🔸-运行时报错：找不到模块&#34;&gt;&lt;a href=&#34;#🔸-运行时报错：找不到模块&#34; class=&#34;headerlink&#34; title=&#34;🔸 运行时报错：找不到模块&#34;&gt;&lt;/a&gt;🔸 运行时报错：找不到模块&lt;/h3&gt;&lt;p&gt;添加隐藏导入模块：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; main.py --hidden-import &lt;span class=&#34;token operator&#34;&gt;&amp;lt;&lt;/span&gt;模块名&lt;span class=&#34;token operator&#34;&gt;&amp;gt;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;🔸-资源文件路径问题&#34;&gt;&lt;a href=&#34;#🔸-资源文件路径问题&#34; class=&#34;headerlink&#34; title=&#34;🔸 资源文件路径问题&#34;&gt;&lt;/a&gt;🔸 资源文件路径问题&lt;/h3&gt;&lt;p&gt;使用下面的函数来获取资源路径（推荐放在开头）：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token function&#34;&gt;import&lt;/span&gt; sys, os

def resource_path&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;:
    &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; hasattr&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;sys, &lt;span class=&#34;token string&#34;&gt;&#34;_MEIPASS&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;:
        &lt;span class=&#34;token builtin class-name&#34;&gt;return&lt;/span&gt; os.path.join&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;sys._MEIPASS, relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    &lt;span class=&#34;token builtin class-name&#34;&gt;return&lt;/span&gt; os.path.join&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;os.path.abspath&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;.&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;, relative_path&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;这样在 &lt;code&gt;.exe&lt;/code&gt; 中也能正确找到资源。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🧠-七、使用-spec-文件自定义打包流程&#34;&gt;&lt;a href=&#34;#🧠-七、使用-spec-文件自定义打包流程&#34; class=&#34;headerlink&#34; title=&#34;🧠 七、使用 .spec 文件自定义打包流程&#34;&gt;&lt;/a&gt;🧠 七、使用 &lt;code&gt;.spec&lt;/code&gt; 文件自定义打包流程&lt;/h2&gt;&lt;p&gt;第一次运行 PyInstaller 时会生成 &lt;code&gt;main.spec&lt;/code&gt; 文件，内容类似：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;&lt;span class=&#34;token comment&#34;&gt;# main.spec&lt;/span&gt;
a &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; Analysis&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;
    &lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;main.py&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;,
    &lt;span class=&#34;token assign-left variable&#34;&gt;pathex&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;,
    &lt;span class=&#34;token assign-left variable&#34;&gt;binaries&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;,
    &lt;span class=&#34;token assign-left variable&#34;&gt;datas&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;config/settings.json&#39;&lt;/span&gt;, &lt;span class=&#34;token string&#34;&gt;&#39;config&#39;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;,
    &lt;span class=&#34;token assign-left variable&#34;&gt;hiddenimports&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;,
&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
exe &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; EXE&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;
    a.scripts, 
    a.binaries, 
    a.zipfiles, 
    a.datas,
    &lt;span class=&#34;token assign-left variable&#34;&gt;name&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;MyApp&#39;&lt;/span&gt;,
    &lt;span class=&#34;token assign-left variable&#34;&gt;console&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;False,   &lt;span class=&#34;token comment&#34;&gt;# False 表示不显示控制台&lt;/span&gt;
    &lt;span class=&#34;token assign-left variable&#34;&gt;icon&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#39;app.ico&#39;&lt;/span&gt;
&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;之后可以直接运行：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;pyinstaller main.spec&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;blockquote&gt;
&lt;p&gt;这样不必每次输入长长的命令，适合项目固定打包需求。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🔍-八、完整流程总结&#34;&gt;&lt;a href=&#34;#🔍-八、完整流程总结&#34; class=&#34;headerlink&#34; title=&#34;🔍 八、完整流程总结&#34;&gt;&lt;/a&gt;🔍 八、完整流程总结&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;步骤&lt;/th&gt;
&lt;th&gt;命令&lt;/th&gt;
&lt;th&gt;说明&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;1️⃣ 安装 PyInstaller&lt;/td&gt;
&lt;td&gt;&lt;code&gt;pip install pyinstaller&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;准备工具&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;2️⃣ 编写代码&lt;/td&gt;
&lt;td&gt;&lt;code&gt;main.py&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;确保能独立运行&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;3️⃣ 测试运行&lt;/td&gt;
&lt;td&gt;&lt;code&gt;python main.py&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;确认无报错&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;4️⃣ 打包命令&lt;/td&gt;
&lt;td&gt;&lt;code&gt;pyinstaller -F -w main.py&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;一键生成 exe&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;5️⃣ 添加资源&lt;/td&gt;
&lt;td&gt;&lt;code&gt;--add-data &#34;config;config&#34;&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;打包额外文件&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;6️⃣ 添加图标&lt;/td&gt;
&lt;td&gt;&lt;code&gt;-i icon.ico&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;美化图标&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;7️⃣ 生成文件&lt;/td&gt;
&lt;td&gt;查看 &lt;code&gt;dist/&lt;/code&gt; 目录&lt;/td&gt;
&lt;td&gt;直接运行 exe&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;8️⃣ 优化&lt;/td&gt;
&lt;td&gt;使用 UPX 压缩&lt;/td&gt;
&lt;td&gt;减小体积&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;🧰-九、进阶技巧&#34;&gt;&lt;a href=&#34;#🧰-九、进阶技巧&#34; class=&#34;headerlink&#34; title=&#34;🧰 九、进阶技巧&#34;&gt;&lt;/a&gt;🧰 九、进阶技巧&lt;/h2&gt;&lt;ul&gt;
&lt;li&gt;&lt;p&gt;批处理打包脚本（保存为 &lt;code&gt;build.bat&lt;/code&gt;）：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;@echo off
&lt;span class=&#34;token builtin class-name&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; 开始打包 &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;
pyinstaller &lt;span class=&#34;token parameter variable&#34;&gt;-F&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-w&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-i&lt;/span&gt; app.ico &lt;span class=&#34;token parameter variable&#34;&gt;-n&lt;/span&gt; MyApp --add-data &lt;span class=&#34;token string&#34;&gt;&#34;config;config&#34;&lt;/span&gt; main.py
&lt;span class=&#34;token builtin class-name&#34;&gt;echo&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; 打包完成，生成文件在 dist/MyApp.exe &lt;span class=&#34;token operator&#34;&gt;==&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;
pause&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;双击 &lt;code&gt;build.bat&lt;/code&gt; 即可一键生成。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;✅-十、示例打包结果&#34;&gt;&lt;a href=&#34;#✅-十、示例打包结果&#34; class=&#34;headerlink&#34; title=&#34;✅ 十、示例打包结果&#34;&gt;&lt;/a&gt;✅ 十、示例打包结果&lt;/h2&gt;&lt;p&gt;成功后会生成：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-bash&#34; data-language=&#34;bash&#34;&gt;&lt;code class=&#34;language-bash&#34;&gt;dist/
└── MyApp.exe&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;双击即可直接运行，即使目标计算机上&lt;strong&gt;没有安装 Python&lt;/strong&gt;。&lt;/p&gt;

 &lt;h1 id=&#34;Python-运算符&#34;&gt;&lt;a href=&#34;#Python-运算符&#34; class=&#34;headerlink&#34; title=&#34;Python 运算符&#34;&gt;&lt;/a&gt;Python 运算符&lt;/h1&gt;&lt;h2 id=&#34;1-Python-运算符总览&#34;&gt;&lt;a href=&#34;#1-Python-运算符总览&#34; class=&#34;headerlink&#34; title=&#34;1. Python 运算符总览&#34;&gt;&lt;/a&gt;1. Python 运算符总览&lt;/h2&gt;&lt;p&gt;Python 的运算符完整分类如下（官方语法级别）：&lt;/p&gt;
&lt;h3 id=&#34;A-算术运算符&#34;&gt;&lt;a href=&#34;#A-算术运算符&#34; class=&#34;headerlink&#34; title=&#34;A. 算术运算符&#34;&gt;&lt;/a&gt;A. 算术运算符&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;+  -  *  /  //  %  **&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;B-比较（关系）运算符&#34;&gt;&lt;a href=&#34;#B-比较（关系）运算符&#34; class=&#34;headerlink&#34; title=&#34;B. 比较（关系）运算符&#34;&gt;&lt;/a&gt;B. 比较（关系）运算符&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;==  !=  &amp;gt;  &amp;lt;  &amp;gt;=  &amp;lt;=  is  is not&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;C-赋值运算符&#34;&gt;&lt;a href=&#34;#C-赋值运算符&#34; class=&#34;headerlink&#34; title=&#34;C. 赋值运算符&#34;&gt;&lt;/a&gt;C. 赋值运算符&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;=  +=  -=  *=  /=  //=  %=  **=  &amp;amp;=  |=  ^=  &amp;gt;&amp;gt;=  &amp;lt;&amp;lt;=&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;D-逻辑运算符&#34;&gt;&lt;a href=&#34;#D-逻辑运算符&#34; class=&#34;headerlink&#34; title=&#34;D. 逻辑运算符&#34;&gt;&lt;/a&gt;D. 逻辑运算符&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;and  or  not&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;E-位运算符&#34;&gt;&lt;a href=&#34;#E-位运算符&#34; class=&#34;headerlink&#34; title=&#34;E. 位运算符&#34;&gt;&lt;/a&gt;E. 位运算符&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;&amp;amp;  |  ^  ~  &amp;lt;&amp;lt;  &amp;gt;&amp;gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;F-成员运算符&#34;&gt;&lt;a href=&#34;#F-成员运算符&#34; class=&#34;headerlink&#34; title=&#34;F. 成员运算符&#34;&gt;&lt;/a&gt;F. 成员运算符&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;in  not in&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;G-身份运算符&#34;&gt;&lt;a href=&#34;#G-身份运算符&#34; class=&#34;headerlink&#34; title=&#34;G. 身份运算符&#34;&gt;&lt;/a&gt;G. 身份运算符&lt;/h3&gt;&lt;p&gt;&lt;code&gt;is  is not&lt;/code&gt;（对比对象是否同一块内存）&lt;/p&gt;
&lt;h3 id=&#34;H-特殊运算符&#34;&gt;&lt;a href=&#34;#H-特殊运算符&#34; class=&#34;headerlink&#34; title=&#34;H. 特殊运算符&#34;&gt;&lt;/a&gt;H. 特殊运算符&lt;/h3&gt;&lt;p&gt;&lt;code&gt;:=&lt;/code&gt;（海象运算符，Python 3.8+）&lt;/p&gt;
&lt;p&gt;至此为全量列表。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;2-各类运算符-——-详细解释-陷阱&#34;&gt;&lt;a href=&#34;#2-各类运算符-——-详细解释-陷阱&#34; class=&#34;headerlink&#34; title=&#34;2. 各类运算符 —— 详细解释 + 陷阱&#34;&gt;&lt;/a&gt;2. 各类运算符 —— 详细解释 + 陷阱&lt;/h2&gt;&lt;h3 id=&#34;A-算术运算符-1&#34;&gt;&lt;a href=&#34;#A-算术运算符-1&#34; class=&#34;headerlink&#34; title=&#34;A. 算术运算符&#34;&gt;&lt;/a&gt;A. 算术运算符&lt;/h3&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;运算符&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;+&lt;/td&gt;
&lt;td&gt;加法 / 拼接 (str, list)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;-&lt;/td&gt;
&lt;td&gt;减法&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;*&lt;/td&gt;
&lt;td&gt;乘法 / 重复（str * 3）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;/&lt;/td&gt;
&lt;td&gt;真除法（永远返回 float）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;//&lt;/td&gt;
&lt;td&gt;地板除（向下取整）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;%&lt;/td&gt;
&lt;td&gt;取模&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;**&lt;/td&gt;
&lt;td&gt;幂&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;工程陷阱&#34;&gt;&lt;a href=&#34;#工程陷阱&#34; class=&#34;headerlink&#34; title=&#34;工程陷阱&#34;&gt;&lt;/a&gt;工程陷阱&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;code&gt;/&lt;/code&gt; 永远返回 float&lt;/li&gt;
&lt;li&gt;地板除 &lt;code&gt;//&lt;/code&gt; 在负数下表现很容易误解：&lt;br&gt; &lt;code&gt;-3 // 2 == -2&lt;/code&gt;（不是 -1）&lt;/li&gt;
&lt;/ol&gt;
&lt;hr&gt;
&lt;h3 id=&#34;B-比较运算符&#34;&gt;&lt;a href=&#34;#B-比较运算符&#34; class=&#34;headerlink&#34; title=&#34;B. 比较运算符&#34;&gt;&lt;/a&gt;B. 比较运算符&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;== != &amp;gt; &amp;lt; &amp;gt;= &amp;lt;= is is not&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;注意：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;==&lt;/code&gt; 比较值是否相等&lt;/li&gt;
&lt;li&gt;&lt;code&gt;is&lt;/code&gt; 比较内存地址是否相同（对象身份）&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;工程踩坑示例&#34;&gt;&lt;a href=&#34;#工程踩坑示例&#34; class=&#34;headerlink&#34; title=&#34;工程踩坑示例&#34;&gt;&lt;/a&gt;工程踩坑示例&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;a = 257
b = 257
print(a is b)   # False
print(a == b)   # True&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;因为 Python 对小整数 [-5, 256] 做了缓存。&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;C-赋值运算符-1&#34;&gt;&lt;a href=&#34;#C-赋值运算符-1&#34; class=&#34;headerlink&#34; title=&#34;C. 赋值运算符&#34;&gt;&lt;/a&gt;C. 赋值运算符&lt;/h3&gt;&lt;p&gt;包括复合赋值：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;a += 1
a -= 1
a *= 2
a //= 2
a %= 7
a **= 3&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;复合赋值对可变对象会直接修改原对象&lt;/strong&gt;：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;lst = [1,2]
a = lst
a += [3]
print(lst)     # [1,2,3]，被修改&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;D-逻辑运算符-1&#34;&gt;&lt;a href=&#34;#D-逻辑运算符-1&#34; class=&#34;headerlink&#34; title=&#34;D. 逻辑运算符&#34;&gt;&lt;/a&gt;D. 逻辑运算符&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;and  or  not&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;Python-逻辑运算返回“最后一个被处理的值”&#34;&gt;&lt;a href=&#34;#Python-逻辑运算返回“最后一个被处理的值”&#34; class=&#34;headerlink&#34; title=&#34;Python 逻辑运算返回“最后一个被处理的值”&#34;&gt;&lt;/a&gt;Python 逻辑运算返回“最后一个被处理的值”&lt;/h3&gt;&lt;p&gt;不是返回 True/False。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;核心逻辑：&lt;/strong&gt;&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;表达式&lt;/th&gt;
&lt;th&gt;结果&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;A and B&lt;/td&gt;
&lt;td&gt;若 A 为真 → 返回 B；若 A 为假 → 返回 A&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;A or B&lt;/td&gt;
&lt;td&gt;若 A 为真 → 返回 A；若 A 为假 → 返回 B&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;工程中非常重要：用于空值兜底、简化判断。&#34;&gt;&lt;a href=&#34;#工程中非常重要：用于空值兜底、简化判断。&#34; class=&#34;headerlink&#34; title=&#34;工程中非常重要：用于空值兜底、简化判断。&#34;&gt;&lt;/a&gt;工程中非常重要：用于&lt;strong&gt;空值兜底&lt;/strong&gt;、&lt;strong&gt;简化判断&lt;/strong&gt;。&lt;/h3&gt;&lt;p&gt;例：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;config_value = user_config or default_config&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;如果 user_config 是空 / None，则返回 default_config。&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;E-位运算符-1&#34;&gt;&lt;a href=&#34;#E-位运算符-1&#34; class=&#34;headerlink&#34; title=&#34;E. 位运算符&#34;&gt;&lt;/a&gt;E. 位运算符&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;&amp;amp; | ^ ~ &amp;lt;&amp;lt; &amp;gt;&amp;gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;工业控制、协议解析极为常用（PLC、Modbus、CAN）。&#34;&gt;&lt;a href=&#34;#工业控制、协议解析极为常用（PLC、Modbus、CAN）。&#34; class=&#34;headerlink&#34; title=&#34;工业控制、协议解析极为常用（PLC、Modbus、CAN）。&#34;&gt;&lt;/a&gt;工业控制、协议解析极为常用（PLC、Modbus、CAN）。&lt;/h3&gt;&lt;p&gt;示例：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;status = 0b101101
alarm = status &amp;amp; 0b001000   # 掩码检测第三位&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;F-成员运算符-1&#34;&gt;&lt;a href=&#34;#F-成员运算符-1&#34; class=&#34;headerlink&#34; title=&#34;F. 成员运算符&#34;&gt;&lt;/a&gt;F. 成员运算符&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;in  not in&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;对字符串、列表、字典键等检查成员：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;&#34;a&#34; in [&#34;a&#34;,&#34;b&#34;]
&#34;age&#34; in {&#34;age&#34;:18}&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;G-身份运算符-1&#34;&gt;&lt;a href=&#34;#G-身份运算符-1&#34; class=&#34;headerlink&#34; title=&#34;G. 身份运算符&#34;&gt;&lt;/a&gt;G. 身份运算符&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;is  is not&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;用于判断对象是否完全相同（内存地址一致）。&lt;/p&gt;
&lt;hr&gt;
&lt;h3 id=&#34;H-海象运算符（Python-3-8-）&#34;&gt;&lt;a href=&#34;#H-海象运算符（Python-3-8-）&#34; class=&#34;headerlink&#34; title=&#34;H. 海象运算符（Python 3.8+）&#34;&gt;&lt;/a&gt;H. 海象运算符（Python 3.8+）&lt;/h3&gt;&lt;p&gt;&lt;code&gt;: =&lt;/code&gt; 在表达式内部执行赋值。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;if (n := len(data)) &amp;gt; 0:
    print(&#34;长度：&#34;, n)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;工程上用于节约重复计算。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;3-工程案例教程（重点）&#34;&gt;&lt;a href=&#34;#3-工程案例教程（重点）&#34; class=&#34;headerlink&#34; title=&#34;3. 工程案例教程（重点）&#34;&gt;&lt;/a&gt;3. 工程案例教程（重点）&lt;/h2&gt;&lt;p&gt;下面给你多行业常用运算符的工程级用法。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;3-1-案例-1：SQL-拼接（避免注入-or-的使用逻辑）&#34;&gt;&lt;a href=&#34;#3-1-案例-1：SQL-拼接（避免注入-or-的使用逻辑）&#34; class=&#34;headerlink&#34; title=&#34;3.1 案例 1：SQL 拼接（避免注入 + or 的使用逻辑）&#34;&gt;&lt;/a&gt;3.1 案例 1：SQL 拼接（避免注入 + or 的使用逻辑）&lt;/h2&gt;&lt;p&gt;错误写法（容易 SQL 注入）：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;sql = f&#34;SELECT * FROM user WHERE name=&#39;{name}&#39;&#34;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;正确写法：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;cursor.execute(&#34;SELECT * FROM user WHERE age &amp;gt; %s AND is_active = %s&#34;,
               (age, True))&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;or-逻辑在-SQL-拼接场景中的正确用法&#34;&gt;&lt;a href=&#34;#or-逻辑在-SQL-拼接场景中的正确用法&#34; class=&#34;headerlink&#34; title=&#34;or 逻辑在 SQL 拼接场景中的正确用法&#34;&gt;&lt;/a&gt;or 逻辑在 SQL 拼接场景中的正确用法&lt;/h3&gt;&lt;p&gt;用户输入可能为空，用 or 做兜底：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;name = input_name or &#34;%&#34;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;3-2-案例-2：PLC-数据控制（位运算-逻辑运算）&#34;&gt;&lt;a href=&#34;#3-2-案例-2：PLC-数据控制（位运算-逻辑运算）&#34; class=&#34;headerlink&#34; title=&#34;3.2 案例 2：PLC 数据控制（位运算 + 逻辑运算）&#34;&gt;&lt;/a&gt;3.2 案例 2：PLC 数据控制（位运算 + 逻辑运算）&lt;/h3&gt;&lt;p&gt;读取设备状态：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;status = plc.read_area(...)

# status 是字节数组
run_flag = get_bool(status, 0, 1)  # 第二位
err_flag = get_bool(status, 0, 2)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;控制写入：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;data = bytearray(1)
set_bool(data, 0, 1, True)
plc.write_area(..., data)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;位运算解析复杂状态：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;mask = 0b001100
alarm = (status_byte &amp;amp; mask) != 0&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;3-3-案例-3：数据上下限校验（比较运算符-逻辑）&#34;&gt;&lt;a href=&#34;#3-3-案例-3：数据上下限校验（比较运算符-逻辑）&#34; class=&#34;headerlink&#34; title=&#34;3.3 案例 3：数据上下限校验（比较运算符 + 逻辑）&#34;&gt;&lt;/a&gt;3.3 案例 3：数据上下限校验（比较运算符 + 逻辑）&lt;/h3&gt;&lt;p&gt;你的典型工程代码：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;low, high = 0.0, 200.0
if not (low &amp;lt;= value &amp;lt;= high):
    print(&#34;超限&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;逻辑运算符常用于构造可读性强的判断：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;if value &amp;lt; low or value &amp;gt; high:
    raise ValueError(&#34;越界&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;3-4-案例-4：模型预测（机器学习）&#34;&gt;&lt;a href=&#34;#3-4-案例-4：模型预测（机器学习）&#34; class=&#34;headerlink&#34; title=&#34;3.4 案例 4：模型预测（机器学习）&#34;&gt;&lt;/a&gt;3.4 案例 4：模型预测（机器学习）&lt;/h3&gt;&lt;p&gt;特征缺失时自动兜底：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;temp = row.get(&#34;temp&#34;) or 0
speed = row.get(&#34;speed&#34;) or 1&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;复合赋值实现特征标准化：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;x -= mean
x /= std&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;3-5-案例-5：区块链-哈希&#34;&gt;&lt;a href=&#34;#3-5-案例-5：区块链-哈希&#34; class=&#34;headerlink&#34; title=&#34;3.5 案例 5：区块链 / 哈希&#34;&gt;&lt;/a&gt;3.5 案例 5：区块链 / 哈希&lt;/h3&gt;&lt;p&gt;低层字节数组计算非常依赖位运算：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-none&#34;&gt;&lt;code class=&#34;language-none&#34;&gt;def xor_bytes(a, b):
    return bytes(x ^ y for x, y in zip(a, b))&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;Block nonce 搜索：乘法、加法、复合运算大量使用。&lt;/p&gt;
&lt;hr&gt;
&lt;h2 id=&#34;4-Python-运算符优先级（完整表）&#34;&gt;&lt;a href=&#34;#4-Python-运算符优先级（完整表）&#34; class=&#34;headerlink&#34; title=&#34;4. Python 运算符优先级（完整表）&#34;&gt;&lt;/a&gt;4. Python 运算符优先级（完整表）&lt;/h2&gt;&lt;p&gt;从高到低：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;()&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;x[index]  x()  x.attr&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;**&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;+x  -x  ~x&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;*  /  //  %&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;+  -&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&amp;lt;&amp;lt; &amp;gt;&amp;gt;&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;&amp;amp;&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;^&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;|&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;== != &amp;gt; &amp;lt; &amp;gt;= &amp;lt;= is is not in not in&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;not&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;and&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;or&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;:=&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;=  +=  -= ...&lt;/code&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;工程经验：不要依赖优先级，必要时加括号提升可读性。&lt;/p&gt;

 &lt;h2 id=&#34;Python-Snap7-终极教程：从入门到精通的完整指南&#34;&gt;&lt;a href=&#34;#Python-Snap7-终极教程：从入门到精通的完整指南&#34; class=&#34;headerlink&#34; title=&#34;Python Snap7 终极教程：从入门到精通的完整指南&#34;&gt;&lt;/a&gt;Python Snap7 终极教程：从入门到精通的完整指南&lt;/h2&gt;&lt;p&gt;&lt;code&gt;python-snap7&lt;/code&gt; 是一个功能强大的库，它允许你的 Python 程序作为客户端，直接与西门子 S7 系列 PLC（S7-300, 400, 1200, 1500）进行以太网通信。本教程将重点介绍最常见的数据块 (DB) 读写操作。&lt;/p&gt;
&lt;h3 id=&#34;第-1-步：环境准备&#34;&gt;&lt;a href=&#34;#第-1-步：环境准备&#34; class=&#34;headerlink&#34; title=&#34;第 1 步：环境准备&#34;&gt;&lt;/a&gt;第 1 步：环境准备&lt;/h3&gt;&lt;p&gt;在开始编码之前，必须确保 Python 和 PLC 两端的设置都正确。&lt;/p&gt;
&lt;h4 id=&#34;1-1-Python-端：安装库&#34;&gt;&lt;a href=&#34;#1-1-Python-端：安装库&#34; class=&#34;headerlink&#34; title=&#34;1.1 Python 端：安装库&#34;&gt;&lt;/a&gt;1.1 Python 端：安装库&lt;/h4&gt;&lt;p&gt;这很简单，使用 pip：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Bash&#34; data-language=&#34;Bash&#34;&gt;&lt;code class=&#34;language-Bash&#34;&gt;pip install python-snap7&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;1-2-PLC-端：TIA-Portal-博图-关键设置&#34;&gt;&lt;a href=&#34;#1-2-PLC-端：TIA-Portal-博图-关键设置&#34; class=&#34;headerlink&#34; title=&#34;1.2 PLC 端：TIA Portal (博图) 关键设置&#34;&gt;&lt;/a&gt;1.2 PLC 端：TIA Portal (博图) 关键设置&lt;/h4&gt;&lt;p&gt;如果 PLC 设置不正确，&lt;code&gt;snap7&lt;/code&gt; 永远无法连接或读取数据。&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;启用 PUT/GET 通信 (最重要！)&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;在 TIA Portal 中，双击你的 CPU，打开“设备配置”。&lt;/li&gt;
&lt;li&gt;在“属性” -&amp;gt; “常规” -&amp;gt; “保护与安全” -&amp;gt; “连接机制”中。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;必须勾选&lt;/strong&gt; “允许来自远程伙伴(PLC, HMI, OPC, …)的 PUT/GET 通信”。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;取消“优化的块访问” (读写 DB 块必须)&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;&lt;code&gt;snap7&lt;/code&gt; 依赖“绝对地址”（例如 &lt;code&gt;DB1.DBD4&lt;/code&gt; 对应偏移量 &lt;code&gt;4&lt;/code&gt;）。“优化”的 DB 块没有这种固定地址。&lt;/li&gt;
&lt;li&gt;在你想要通过 &lt;code&gt;snap7&lt;/code&gt; 访问的 &lt;strong&gt;每一个 DB 块&lt;/strong&gt; 上，右键 -&amp;gt; “属性”。&lt;/li&gt;
&lt;li&gt;在“常规” -&amp;gt; “属性”中，&lt;strong&gt;取消勾选&lt;/strong&gt; “优化的块访问”。&lt;/li&gt;
&lt;li&gt;取消后，你需要重新编译并下载硬件和软件配置到 PLC。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;网络设置&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;确保你的 Python 计算机和 PLC 在同一个 IP 子网内，并且彼此可以 &lt;code&gt;ping&lt;/code&gt; 通。&lt;/li&gt;
&lt;li&gt;记下 PLC 的 IP 地址。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Rack (机架) 和 Slot (插槽)&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;这是 S7 协议的寻址方式。&lt;/li&gt;
&lt;li&gt;对于 &lt;strong&gt;S7-1200 / S7-1500&lt;/strong&gt;，CPU 通常是 &lt;strong&gt;Rack = 0, Slot = 1&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;对于 &lt;strong&gt;S7-300&lt;/strong&gt;，CPU 通常是 &lt;strong&gt;Rack = 0, Slot = 2&lt;/strong&gt;。&lt;/li&gt;
&lt;li&gt;你可以在 TIA Portal 的设备视图中确认。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;第-2-步：连接与断开-PLC&#34;&gt;&lt;a href=&#34;#第-2-步：连接与断开-PLC&#34; class=&#34;headerlink&#34; title=&#34;第 2 步：连接与断开 PLC&#34;&gt;&lt;/a&gt;第 2 步：连接与断开 PLC&lt;/h3&gt;&lt;p&gt;一个健壮的程序总是使用 &lt;code&gt;try...except...finally&lt;/code&gt; 来确保连接被正确关闭。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;import snap7
import snap7.client as c
from snap7.util import *
import time

# --- PLC 连接参数 ---
PLC_IP = &#39;192.168.0.1&#39;   # 替换成你的 PLC IP
PLC_RACK = 0             # 默认 0
PLC_SLOT = 1             # S7-1200/1500 默认 1 (S7-300 默认 2)

# --- 实例化客户端 ---
plc = c.Client()

try:
    # --- 建立连接 ---
    print(f&#34;正在连接 PLC ({PLC_IP})...&#34;)
    plc.connect(PLC_IP, PLC_RACK, PLC_SLOT)

    # --- 检查连接状态 ---
    if plc.get_connected():
        print(&#34;连接成功！&#34;)

        # --- 获取 PLC CPU 状态 (可选) ---
        # 0x04 = STOP, 0x08 = RUN
        cpu_state_raw = plc.get_cpu_state()
        print(f&#34;PLC 状态: {cpu_state_raw}&#34;) # &#39;S7CpuStatusRun&#39;, &#39;S7CpuStatusStop&#39;

        # ... 
        # ... 接下来所有的读写操作都在这个 &#39;if&#39; 块中进行 ...
        # ...

    else:
        print(&#34;连接失败。请检查：&#34;)
        print(&#34;1. IP 地址是否正确？&#34;)
        print(&#34;2. Rack/Slot 是否正确？ (S7-1200/1500 通常是 0 和 1)&#34;)
        print(&#34;3. TIA Portal 中是否勾选了 &#39;PUT/GET&#39; 权限？&#34;)
        print(&#34;4. 网络是否可达 (ping)？&#34;)

except snap7.snap7exceptions.Snap7Exception as e:
    # 捕获 Snap7 可能的连接异常
    print(f&#34;连接时发生 Snap7 错误: {e}&#34;)
except Exception as e:
    print(f&#34;发生未知错误: {e}&#34;)

finally:
    # --- 断开连接 ---
    # 确保无论程序成功还是失败，都断开连接释放 PLC 资源
    if plc.get_connected():
        plc.disconnect()
        print(&#34;已断开 PLC 连接。&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;第-3-步：核心-读取不同类型的数据&#34;&gt;&lt;a href=&#34;#第-3-步：核心-读取不同类型的数据&#34; class=&#34;headerlink&#34; title=&#34;第 3 步：核心 - 读取不同类型的数据&#34;&gt;&lt;/a&gt;第 3 步：核心 - 读取不同类型的数据&lt;/h3&gt;&lt;p&gt;所有读取操作都返回一个 &lt;code&gt;bytearray&lt;/code&gt;。我们必须使用 &lt;code&gt;snap7.util&lt;/code&gt; 库中的辅助函数来将其转换为 Python 数据类型。&lt;/p&gt;
&lt;p&gt;我们将创建一系列函数，&lt;strong&gt;假设这些函数都在 &lt;code&gt;if plc.get_connected():&lt;/code&gt; 块内被调用&lt;/strong&gt;。&lt;/p&gt;
&lt;h4 id=&#34;3-1-读取-BOOL-位&#34;&gt;&lt;a href=&#34;#3-1-读取-BOOL-位&#34; class=&#34;headerlink&#34; title=&#34;3.1 读取 BOOL (位)&#34;&gt;&lt;/a&gt;3.1 读取 BOOL (位)&lt;/h4&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;PLC 地址&lt;/strong&gt;: &lt;code&gt;DB1.DBX0.0&lt;/code&gt; (DB 块 1, 字节 0, 位 0)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;方法&lt;/strong&gt;: 你不能只读 1 个位，你必须读取它所在的&lt;strong&gt;整个字节&lt;/strong&gt; (1 byte)，然后再解析出那个位。&lt;/li&gt;
&lt;/ul&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;def read_single_bool(client: c.Client, db_number: int, byte_index: int, bit_index: int):
    &#34;&#34;&#34;
    从PLC的一个特定DB地址读取单个BOOL值。
    &#34;&#34;&#34;
    try:
        # 1. 读取包含该位的 1 个字节
        byte_data = client.db_read(db_number, byte_index, 1)

        # 2. 从读取到的字节中解析出指定的位
        #    get_bool(bytearray, 字节索引, 位索引)
        value = get_bool(byte_data, 0, bit_index)
        return value
    except Exception as e:
        print(f&#34;读取 DB{db_number}.DBX{byte_index}.{bit_index} (BOOL) 失败: {e}&#34;)
        return None

# --- 调用示例 ---
# is_running = read_single_bool(plc, 1, 0, 0) # 读取 DB1.DBX0.0
# if is_running is not None:
#     print(f&#34;DB1.DBX0.0 的值: {is_running}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;3-2-读取-REAL-32位-浮点数&#34;&gt;&lt;a href=&#34;#3-2-读取-REAL-32位-浮点数&#34; class=&#34;headerlink&#34; title=&#34;3.2 读取 REAL (32位 浮点数)&#34;&gt;&lt;/a&gt;3.2 读取 REAL (32位 浮点数)&lt;/h4&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;PLC 地址&lt;/strong&gt;: &lt;code&gt;DB1.DBD4&lt;/code&gt; (DB 块 1, 从第 4 字节开始的双字)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;方法&lt;/strong&gt;: &lt;code&gt;REAL&lt;/code&gt; 占用 &lt;strong&gt;4 个字节&lt;/strong&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;def read_single_real(client: c.Client, db_number: int, start_byte_index: int):
    &#34;&#34;&#34;
    从PLC的一个特定DB地址读取单个REAL (浮点数)。
    &#34;&#34;&#34;
    try:
        # 1. 读取 4 个字节
        byte_data = client.db_read(db_number, start_byte_index, 4)

        # 2. 使用 get_real 解析
        #    get_real(bytearray, 字节索引)
        value = get_real(byte_data, 0)
        return value
    except Exception as e:
        print(f&#34;读取 DB{db_number}.DBD{start_byte_index} (REAL) 失败: {e}&#34;)
        return None

# --- 调用示例 ---
# temperature = read_single_real(plc, 1, 4) # 读取 DB1.DBD4
# if temperature is not None:
#     print(f&#34;DB1.DBD4 (温度) 的值: {temperature:.2f}&#34;) # 格式化为2位小数&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;3-3-读取-INT-16位-整数&#34;&gt;&lt;a href=&#34;#3-3-读取-INT-16位-整数&#34; class=&#34;headerlink&#34; title=&#34;3.3 读取 INT (16位 整数)&#34;&gt;&lt;/a&gt;3.3 读取 INT (16位 整数)&lt;/h4&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;PLC 地址&lt;/strong&gt;: &lt;code&gt;DB1.DBW2&lt;/code&gt; (DB 块 1, 从第 2 字节开始的字)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;方法&lt;/strong&gt;: &lt;code&gt;INT&lt;/code&gt; 占用 &lt;strong&gt;2 个字节&lt;/strong&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;def read_single_int(client: c.Client, db_number: int, start_byte_index: int):
    &#34;&#34;&#34;
    从PLC的一个特定DB地址读取单个INT (16位整数)。
    &#34;&#34;&#34;
    try:
        # 1. 读取 2 个字节
        byte_data = client.db_read(db_number, start_byte_index, 2)

        # 2. 使用 get_int 解析
        value = get_int(byte_data, 0)
        return value
    except Exception as e:
        print(f&#34;读取 DB{db_number}.DBW{start_byte_index} (INT) 失败: {e}&#34;)
        return None

# --- 调用示例 ---
# item_count = read_single_int(plc, 1, 2) # 读取 DB1.DBW2
# if item_count is not None:
#     print(f&#34;DB1.DBW2 (计数值) 的值: {item_count}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;3-4-读取-DINT-32位-整数&#34;&gt;&lt;a href=&#34;#3-4-读取-DINT-32位-整数&#34; class=&#34;headerlink&#34; title=&#34;3.4 读取 DINT (32位 整数)&#34;&gt;&lt;/a&gt;3.4 读取 DINT (32位 整数)&lt;/h4&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;PLC 地址&lt;/strong&gt;: &lt;code&gt;DB1.DBD8&lt;/code&gt; (DB 块 1, 从第 8 字节开始的双字)&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;方法&lt;/strong&gt;: &lt;code&gt;DINT&lt;/code&gt; 占用 &lt;strong&gt;4 个字节&lt;/strong&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;def read_single_dint(client: c.Client, db_number: int, start_byte_index: int):
    &#34;&#34;&#34;
    从PLC的一个特定DB地址读取单个DINT (32位整数)。
    &#34;&#34;&#34;
    try:
        # 1. 读取 4 个字节
        byte_data = client.db_read(db_number, start_byte_index, 4)

        # 2. 使用 get_dint 解析
        value = get_dint(byte_data, 0)
        return value
    except Exception as e:
        print(f&#34;读取 DB{db_number}.DBD{start_byte_index} (DINT) 失败: {e}&#34;)
        return None

# --- 调用示例 ---
# large_value = read_single_dint(plc, 1, 8) # 读取 DB1.DBD8
# if large_value is not None:
#     print(f&#34;DB1.DBD8 (DINT值) 的值: {large_value}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;3-5-读取-M-区-I-区-Q-区-以-M0-0-为例&#34;&gt;&lt;a href=&#34;#3-5-读取-M-区-I-区-Q-区-以-M0-0-为例&#34; class=&#34;headerlink&#34; title=&#34;3.5 读取 M 区 / I 区 / Q 区 (以 M0.0 为例)&#34;&gt;&lt;/a&gt;3.5 读取 M 区 / I 区 / Q 区 (以 M0.0 为例)&lt;/h4&gt;&lt;p&gt;如果你想读取 M、I (输入) 或 Q (输出) 区域，使用 &lt;code&gt;read_area&lt;/code&gt;。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;snap7.types.Area.MK&lt;/code&gt; -&amp;gt; M 区&lt;/li&gt;
&lt;li&gt;&lt;code&gt;snap7.types.Area.PE&lt;/code&gt; -&amp;gt; I 区 (输入)&lt;/li&gt;
&lt;li&gt;&lt;code&gt;snap7.types.Area.PA&lt;/code&gt; -&amp;gt; Q 区 (输出)&lt;/li&gt;
&lt;/ul&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;try:
    # 读取 M0.0 (第 0 字节, 第 0 位)
    # read_area(area, db_number, start, size)
    # M区没有db_number，所以填 0
    m_byte = plc.read_area(snap7.types.Area.MK, 0, 0, 1)
    m0_0_value = get_bool(m_byte, 0, 0)
    print(f&#34;M0.0 的值: {m0_0_value}&#34;)

    # 读取 IW0 (输入字 0，占用2字节)
    i_word = plc.read_area(snap7.types.Area.PE, 0, 0, 2)
    iw0_value = get_int(i_word, 0)
    print(f&#34;IW0 的值: {iw0_value}&#34;)

except Exception as e:
    print(f&#34;读取 M/I/Q 区失败: {e}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;3-6-读取-STRING-S7-字符串&#34;&gt;&lt;a href=&#34;#3-6-读取-STRING-S7-字符串&#34; class=&#34;headerlink&#34; title=&#34;3.6 读取 STRING (S7 字符串)&#34;&gt;&lt;/a&gt;3.6 读取 STRING (S7 字符串)&lt;/h4&gt;&lt;p&gt;PLC 地址: &lt;code&gt;DB1.DBB10 (STRING[50])&lt;/code&gt; (DB 块 1, 从第 10 字节开始, 假设最大长度 50)&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;方法&lt;/strong&gt;: &lt;code&gt;STRING&lt;/code&gt; 在 PLC 中存储很特殊。一个 &lt;code&gt;STRING[50]&lt;/code&gt; 占用 52 个字节：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;第 1 字节: 最大长度 (值总是 50)&lt;/li&gt;
&lt;li&gt;第 2 字节: 实际长度 (例如 ‘ABC’ 长度为 3)&lt;/li&gt;
&lt;li&gt;后面 50 字节: 实际的 ASCII 字符&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;code&gt;snap7&lt;/code&gt; 库简化了这个过程。我们&lt;strong&gt;必须读取所有 52 个字节&lt;/strong&gt; (&lt;code&gt;max_len + 2&lt;/code&gt;)，&lt;code&gt;get_string&lt;/code&gt; 函数会智能地解析它。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;def read_string(client: c.Client, db_number: int, start_byte_index: int, max_string_len: int):
    &#34;&#34;&#34;
    从PLC的一个特定DB地址读取S7 STRING。
    :param max_string_len: 字符串在 TIA Portal 中定义的*最大*长度，例如 STRING[50] -&amp;gt; 50
    &#34;&#34;&#34;
    try:
        # 1. 读取总共 (最大长度 + 2) 个字节
        total_bytes = max_string_len + 2
        byte_data = client.db_read(db_number, start_byte_index, total_bytes)

        # 2. 使用 get_string 解析
        #    get_string(bytearray, 字节索引)
        #    它会自动处理头部的 2 个字节，并返回实际的字符串
        value = get_string(byte_data, 0)
        return value
    except Exception as e:
        print(f&#34;读取 DB{db_number}.DBB{start_byte_index} (STRING[{max_string_len}]) 失败: {e}&#34;)
        return None

# --- 调用示例 ---
# model_name = read_string(plc, 1, 10, 50) # 假设 DB1.DBB10 是 STRING[50]
# if model_name is not None:
#     print(f&#34;DB1.DBB10 (型号) 的值: {model_name}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;第-4-步：核心-写入不同类型的数据&#34;&gt;&lt;a href=&#34;#第-4-步：核心-写入不同类型的数据&#34; class=&#34;headerlink&#34; title=&#34;第 4 步：核心 - 写入不同类型的数据&#34;&gt;&lt;/a&gt;第 4 步：核心 - 写入不同类型的数据&lt;/h3&gt;&lt;p&gt;写入是读取的逆过程：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;创建一个正确大小的 &lt;code&gt;bytearray&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;使用 &lt;code&gt;snap7.util.set_...&lt;/code&gt; 函数将 Python 值“填充”到 &lt;code&gt;bytearray&lt;/code&gt; 中。&lt;/li&gt;
&lt;li&gt;调用 &lt;code&gt;db_write()&lt;/code&gt; 将 &lt;code&gt;bytearray&lt;/code&gt; 发送到 PLC。&lt;/li&gt;
&lt;/ol&gt;
&lt;h4 id=&#34;4-1-写入-BOOL-位-【最特殊】&#34;&gt;&lt;a href=&#34;#4-1-写入-BOOL-位-【最特殊】&#34; class=&#34;headerlink&#34; title=&#34;4.1 写入 BOOL (位) - 【最特殊】&#34;&gt;&lt;/a&gt;4.1 写入 BOOL (位) - 【最特殊】&lt;/h4&gt;&lt;p&gt;&lt;strong&gt;警告&lt;/strong&gt;: 你不能只写入 1 个位。这样做会覆盖同一字节中的其他 7 个位。 你必须使用 &lt;strong&gt;“读-改-写” (Read-Modify-Write)&lt;/strong&gt; 模式。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;def write_single_bool(client: c.Client, db_number: int, byte_index: int, bit_index: int, value: bool):
    &#34;&#34;&#34;
    使用 &#34;读-改-写&#34; 模式安全地写入单个BOOL值。
    &#34;&#34;&#34;
    try:
        # 1. 读: 读取当前的整个字节
        byte_data = client.db_read(db_number, byte_index, 1)

        # 2. 改: 在 Python 内存中修改那个位
        #    set_bool(bytearray, 字节索引, 位索引, 值)
        set_bool(byte_data, 0, bit_index, value)

        # 3. 写: 把修改后的整个字节写回去
        client.db_write(db_number, byte_index, byte_data)
        return True
    except Exception as e:
        print(f&#34;写入 DB{db_number}.DBX{byte_index}.{bit_index} (BOOL) 失败: {e}&#34;)
        return False

# --- 调用示例 ---
# print(&#34;正在写入 True 到 DB1.DBX0.1...&#34;)
# success = write_single_bool(plc, 1, 0, 1, True) # 写入 DB1.DBX0.1
# if success:
#     print(&#34;写入成功。&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;4-2-写入-REAL-32位-浮点数&#34;&gt;&lt;a href=&#34;#4-2-写入-REAL-32位-浮点数&#34; class=&#34;headerlink&#34; title=&#34;4.2 写入 REAL (32位 浮点数)&#34;&gt;&lt;/a&gt;4.2 写入 REAL (32位 浮点数)&lt;/h4&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;PLC 地址&lt;/strong&gt;: &lt;code&gt;DB1.DBD4&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;def write_single_real(client: c.Client, db_number: int, start_byte_index: int, value: float):
    &#34;&#34;&#34;
    向PLC的一个特定DB地址写入单个REAL (浮点数)。
    &#34;&#34;&#34;
    try:
        # 1. 创建 4 字节的 bytearray
        data_to_write = bytearray(4)

        # 2. 将浮点数值填充到 bytearray
        #    set_real(bytearray, 字节索引, 值)
        set_real(data_to_write, 0, value)

        # 3. 写入 PLC
        client.db_write(db_number, start_byte_index, data_to_write)
        return True
    except Exception as e:
        print(f&#34;写入 DB{db_number}.DBD{start_byte_index} (REAL) 失败: {e}&#34;)
        return False

# --- 调用示例 ---
# new_temp = 98.6
# print(f&#34;正在写入 {new_temp} 到 DB1.DBD4...&#34;)
# success = write_single_real(plc, 1, 4, new_temp)
# if success:
#     print(&#34;写入成功。&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;4-3-写入-INT-16位-整数&#34;&gt;&lt;a href=&#34;#4-3-写入-INT-16位-整数&#34; class=&#34;headerlink&#34; title=&#34;4.3 写入 INT (16位 整数)&#34;&gt;&lt;/a&gt;4.3 写入 INT (16位 整数)&lt;/h4&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;PLC 地址&lt;/strong&gt;: &lt;code&gt;DB1.DBW2&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;def write_single_int(client: c.Client, db_number: int, start_byte_index: int, value: int):
    &#34;&#34;&#34;
    向PLC的一个特定DB地址写入单个INT (16位整数)。
    &#34;&#34;&#34;
    try:
        # 1. 创建 2 字节的 bytearray
        data_to_write = bytearray(2)

        # 2. 填充
        set_int(data_to_write, 0, value)

        # 3. 写入
        client.db_write(db_number, start_byte_index, data_to_write)
        return True
    except Exception as e:
        print(f&#34;写入 DB{db_number}.DBW{start_byte_index} (INT) 失败: {e}&#34;)
        return False

# --- 调用示例 ---
# new_count = 500
# print(f&#34;正在写入 {new_count} 到 DB1.DBW2...&#34;)
# success = write_single_int(plc, 1, 2, new_count)
# if success:
#     print(&#34;写入成功。&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;4-4写入-DINT-32位-整数&#34;&gt;&lt;a href=&#34;#4-4写入-DINT-32位-整数&#34; class=&#34;headerlink&#34; title=&#34;4.4写入 DINT (32位 整数)&#34;&gt;&lt;/a&gt;4.4写入 DINT (32位 整数)&lt;/h4&gt;&lt;p&gt;PLC 地址: &lt;code&gt;DB1.DBD8&lt;/code&gt;&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;def write_single_dint(client: c.Client, db_number: int, start_byte_index: int, value: int):
    &#34;&#34;&#34;
    向PLC的一个特定DB地址写入单个DINT (32位整数)。
    &#34;&#34;&#34;
    try:
        # 1. 创建 4 字节的 bytearray
        data_to_write = bytearray(4)

        # 2. 填充
        set_dint(data_to_write, 0, value)

        # 3. 写入
        client.db_write(db_number, start_byte_index, data_to_write)
        return True
    except Exception as e:
        print(f&#34;写入 DB{db_number}.DBD{start_byte_index} (DINT) 失败: {e}&#34;)
        return False

# --- 调用示例 ---
# large_count = 1234567
# print(f&#34;正在写入 {large_count} 到 DB1.DBD8...&#34;)
# success = write_single_dint(plc, 1, 8, large_count)
# if success:
#     print(&#34;写入成功。&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;4-5-写入-STRING-S7-字符串&#34;&gt;&lt;a href=&#34;#4-5-写入-STRING-S7-字符串&#34; class=&#34;headerlink&#34; title=&#34;4.5 写入 STRING (S7 字符串)&#34;&gt;&lt;/a&gt;4.5 写入 STRING (S7 字符串)&lt;/h4&gt;&lt;p&gt;PLC 地址: &lt;code&gt;DB1.DBB10 (STRING[50])&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;方法&lt;/strong&gt;: &lt;code&gt;set_string&lt;/code&gt; 辅助函数非常智能。它会为我们自动创建 2 字节的头部（最大长度和实际长度）。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;def write_string(client: c.Client, db_number: int, start_byte_index: int, value: str, max_string_len: int):
    &#34;&#34;&#34;
    向PLC的一个特定DB地址写入S7 STRING。
    如果 value 超过 max_string_len，它将被自动截断。
    &#34;&#34;&#34;
    try:
        # 1. 创建 (最大长度 + 2) 字节的 bytearray
        total_bytes = max_string_len + 2
        data_to_write = bytearray(total_bytes)

        # 2. 使用 set_string 填充
        #    set_string(bytearray, 字节索引, 字符串值, 最大字符串长度)
        set_string(data_to_write, 0, value, max_string_len)

        # 3. 写入
        client.db_write(db_number, start_byte_index, data_to_write)
        return True
    except Exception as e:
        print(f&#34;写入 DB{db_number}.DBB{start_byte_index} (STRING) 失败: {e}&#34;)
        return False

# --- 调用示例 ---
# new_model_name = &#34;Model-XYZ-2025&#34;
# print(f&#34;正在写入 &#39;{new_model_name}&#39; 到 DB1.DBB10...&#34;)
# success = write_string(plc, 1, 10, new_model_name, 50) # 假设是 STRING[50]
# if success:
#     print(&#34;写入成功。&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h3 id=&#34;第-5-步：性能优化与最佳实践&#34;&gt;&lt;a href=&#34;#第-5-步：性能优化与最佳实践&#34; class=&#34;headerlink&#34; title=&#34;第 5 步：性能优化与最佳实践&#34;&gt;&lt;/a&gt;第 5 步：性能优化与最佳实践&lt;/h3&gt;&lt;h4 id=&#34;1-批量读写-最重要的性能技巧&#34;&gt;&lt;a href=&#34;#1-批量读写-最重要的性能技巧&#34; class=&#34;headerlink&#34; title=&#34;1. 批量读写 (最重要的性能技巧)&#34;&gt;&lt;/a&gt;1. 批量读写 (最重要的性能技巧)&lt;/h4&gt;&lt;p&gt;&lt;strong&gt;不要&lt;/strong&gt; 像这样在循环中单独读取数据：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# 错误的方式 (非常慢！)：
start_time = time.time()
value_list = []
for i in range(10):
    # 每次循环都是一次完整的网络请求
    value_list.append(read_single_real(plc, 1, 4 + i*4))
print(f&#34;读取 10 个 REAL (循环) 耗时: {time.time() - start_time:.4f} 秒&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;&lt;strong&gt;要&lt;/strong&gt; 一次性读取一个大数据块，然后在 Python 中解析：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# 正确的方式 (非常快！)：
DB_NUM = 1
START_OFFSET = 4
NUM_REALS = 10
READ_SIZE_BYTES = NUM_REALS * 4 # 10 个 REAL * 4 字节/REAL

start_time = time.time()

try:
    # 1. 一次性读取 40 个字节
    all_data = plc.db_read(DB_NUM, START_OFFSET, READ_SIZE_BYTES)

    value_list = []
    # 2. 在 Python 内存中循环解析 (这几乎不花时间)
    for i in range(NUM_REALS):
        byte_offset = i * 4
        value = get_real(all_data, byte_offset)
        value_list.append(value)

    print(f&#34;读取 10 个 REAL (批量) 耗时: {time.time() - start_time:.4f} 秒&#34;)
    # print(value_list)

except Exception as e:
    print(f&#34;批量读取失败: {e}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;网络延迟是瓶颈，而不是 Python 的解析速度。批量操作可以将性能提升 100 倍以上。写入也是同理。&lt;/p&gt;
&lt;h4 id=&#34;5-2-批量写入-Batch-Write&#34;&gt;&lt;a href=&#34;#5-2-批量写入-Batch-Write&#34; class=&#34;headerlink&#34; title=&#34;5.2 批量写入 (Batch Write)&#34;&gt;&lt;/a&gt;5.2 批量写入 (Batch Write)&lt;/h4&gt;&lt;p&gt;&lt;strong&gt;原理&lt;/strong&gt;: 与批量读取相同。不要在循环中单独写入，而是在 Python 中**构建一个大的 &lt;code&gt;bytearray&lt;/code&gt;**，然后一次性将其写入 PLC。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;示例&lt;/strong&gt;: 假设我们要一次性写入 &lt;code&gt;DB1.DBD4&lt;/code&gt; (REAL), &lt;code&gt;DB1.DBD8&lt;/code&gt; (DINT) 和 &lt;code&gt;DB1.DBW12&lt;/code&gt; (INT)。这 3 个变量在 DB 块中是连续的。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;DBD4&lt;/code&gt; (REAL) @ 偏移 4, 长度 4&lt;/li&gt;
&lt;li&gt;&lt;code&gt;DBD8&lt;/code&gt; (DINT) @ 偏移 8, 长度 4&lt;/li&gt;
&lt;li&gt;&lt;code&gt;DBW12&lt;/code&gt; (INT) @ 偏移 12, 长度 2&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;总数据块从 &lt;code&gt;DBB4&lt;/code&gt; 开始，到 &lt;code&gt;DBB13&lt;/code&gt; 结束，总长度 &lt;code&gt;(12 + 2) - 4 = 10&lt;/code&gt; 字节。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;# --- 批量写入示例 ---
DB_NUM = 1
START_OFFSET = 4
TOTAL_SIZE = 10 # 4 (REAL) + 4 (DINT) + 2 (INT)

print(&#34;正在准备批量写入...&#34;)
try:
    # 1. 创建一个 10 字节的空 bytearray
    all_data_to_write = bytearray(TOTAL_SIZE)

    # 2. 在 Python 内存中填充数据
    #    注意偏移量是相对于这个 bytearray 的
    set_real(all_data_to_write, 0, 99.9)      # 写入 DBD4 (偏移 0)
    set_dint(all_data_to_write, 4, 123456)   # 写入 DBD8 (偏移 4)
    set_int(all_data_to_write, 8, -500)      # 写入 DBW12 (偏移 8)

    # 3. 一次性写入 10 个字节
    plc.db_write(DB_NUM, START_OFFSET, all_data_to_write)
    print(&#34;批量写入成功！&#34;)

except Exception as e:
    print(f&#34;批量写入失败: {e}&#34;)&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;5-3-终极性能：Multi-Read-Multi-Write&#34;&gt;&lt;a href=&#34;#5-3-终极性能：Multi-Read-Multi-Write&#34; class=&#34;headerlink&#34; title=&#34;5.3 终极性能：Multi-Read / Multi-Write&#34;&gt;&lt;/a&gt;5.3 终极性能：Multi-Read / Multi-Write&lt;/h4&gt;&lt;p&gt;&lt;strong&gt;原理&lt;/strong&gt;: 当你需要读取的数据&lt;strong&gt;不连续&lt;/strong&gt;，甚至&lt;strong&gt;不在同一个 DB 块或内存区&lt;/strong&gt;时（例如，&lt;code&gt;DB1.DBD4&lt;/code&gt;, &lt;code&gt;DB10.DBW0&lt;/code&gt;, &lt;code&gt;M0.0&lt;/code&gt;），使用 &lt;code&gt;read_multi()&lt;/code&gt;。它将所有请求打包成一个，发给 PLC，PLC 再返回所有结果。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;方法&lt;/strong&gt;: &lt;code&gt;read_multi()&lt;/code&gt; 接受一个 &lt;code&gt;S7Map&lt;/code&gt; 对象列表。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;from snap7.types import S7Map, S7AreaDB, S7AreaMK, S7WLReal, S7WLWord, S7WLBit

print(&#34;正在准备多区域读取...&#34;)

# 1. 定义你要读取的所有变量
# S7Map(Area, DBNumber, Start, Size)
items_to_read = (
    # 项 1: DB1.DBD4 (REAL, 4 字节)
    S7Map(S7AreaDB, 1, 4, 4), 

    # 项 2: DB10.DBW0 (INT, 2 字节)
    S7Map(S7AreaDB, 10, 0, 2),

    # 项 3: M0.0 (BOOL, 1 字节中的 1 位)
    # 注意：读取 BOOL 仍然需要读取 1 整个字节
    S7Map(S7AreaMK, 0, 0, 1) 
)

try:
    # 2. 一次性读取所有项
    # plc.read_multi() 返回一个 S7Map 结果的列表
    results = plc.read_multi(items_to_read)

    # 3. 单独解析每个结果
    # 结果的顺序与你请求的顺序一致

    # 结果 0: DB1.DBD4
    # (结果是一个 bytearray)
    val_real = get_real(results[0], 0)
    print(f&#34;Multi-Read [DB1.DBD4]: {val_real}&#34;)

    # 结果 1: DB10.DBW0
    val_int = get_int(results[1], 0)
    print(f&#34;Multi-Read [DB10.DBW0]: {val_int}&#34;)

    # 结果 2: M0.0
    val_bool = get_bool(results[2], 0, 0)
    print(f&#34;Multi-Read [M0.0]: {val_bool}&#34;)

except Exception as e:
    print(f&#34;多区域读取 (read_multi) 失败: {e}&#34;)

# write_multi() 的用法完全相同，只是你需要先准备 S7Map 列表和
# 对应的 data 列表，然后调用 plc.write_multi(items, data)。&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h4 id=&#34;4-完整性检查&#34;&gt;&lt;a href=&#34;#4-完整性检查&#34; class=&#34;headerlink&#34; title=&#34;4. 完整性检查&#34;&gt;&lt;/a&gt;4. 完整性检查&lt;/h4&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;再次检查 TIA Portal 设置&lt;/strong&gt;: &lt;code&gt;PUT/GET&lt;/code&gt; 和 &lt;code&gt;优化的块访问&lt;/code&gt; 是所有问题的根源。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;使用 &lt;code&gt;try...finally&lt;/code&gt;&lt;/strong&gt;: 始终确保 &lt;code&gt;plc.disconnect()&lt;/code&gt; 被调用，否则你可能会耗尽 PLC 的连接资源（它可能只允许 8-16 个并发连接）。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;第-6-步：完整可运行示例&#34;&gt;&lt;a href=&#34;#第-6-步：完整可运行示例&#34; class=&#34;headerlink&#34; title=&#34;第 6 步：完整可运行示例&#34;&gt;&lt;/a&gt;第 6 步：完整可运行示例&lt;/h3&gt;&lt;p&gt;这个脚本将所有内容（连接、辅助函数、读/写调用、断开）组合在一起。&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-Python&#34; data-language=&#34;Python&#34;&gt;&lt;code class=&#34;language-Python&#34;&gt;#!/usr/bin/env python
# -*- coding: utf-8 -*-

&#34;&#34;&#34;
Python-Snap7 终极教程 - 完整示例脚本
&#34;&#34;&#34;

import snap7
import snap7.client as c
from snap7.util import *
import time

# --- PLC 连接参数 ---
PLC_IP = &#39;192.168.0.1&#39;   # 替换成你的 PLC IP
PLC_RACK = 0            # 默认 0
PLC_SLOT = 1            # S7-1200/1500 默认 1 (S7-300 默认 2)

# --- DB 和地址定义 (仅为示例) ---
DB_NUM = 1
# 地址
ADDR_BOOL_R = &#39;DBX0.0&#39;   # (Byte 0, Bit 0)
ADDR_BOOL_W = &#39;DBX0.1&#39;   # (Byte 0, Bit 1)
ADDR_INT_RW = &#39;DBW2&#39;     # (Byte 2)
ADDR_REAL_RW = &#39;DBD4&#39;    # (Byte 4)
ADDR_STRING_RW = &#39;DBB10&#39; # (Byte 10)
STRING_MAX_LEN = 50      # 假设是 STRING[50]

# ----------------------------------------------------
# 步骤 3 &amp;amp; 4：定义所有读写辅助函数
# ----------------------------------------------------
# （为了简洁，这里省略了函数的 DocString，请参考上面教程中的定义）

def read_single_bool(client: c.Client, db_number: int, byte_index: int, bit_index: int):
    try:
        byte_data = client.db_read(db_number, byte_index, 1)
        value = get_bool(byte_data, 0, bit_index)
        return value
    except Exception as e:
        print(f&#34;读取 DB{db_number}.DBX{byte_index}.{bit_index} 失败: {e}&#34;)
        return None

def write_single_bool(client: c.Client, db_number: int, byte_index: int, bit_index: int, value: bool):
    try:
        byte_data = client.db_read(db_number, byte_index, 1) # 1. 读
        set_bool(byte_data, 0, bit_index, value)             # 2. 改
        client.db_write(db_number, byte_index, byte_data)    # 3. 写
        return True
    except Exception as e:
        print(f&#34;写入 DB{db_number}.DBX{byte_index}.{bit_index} 失败: {e}&#34;)
        return False

def read_single_real(client: c.Client, db_number: int, start_byte_index: int):
    try:
        byte_data = client.db_read(db_number, start_byte_index, 4)
        value = get_real(byte_data, 0)
        return value
    except Exception as e:
        print(f&#34;读取 DB{db_number}.DBD{start_byte_index} 失败: {e}&#34;)
        return None

def write_single_real(client: c.Client, db_number: int, start_byte_index: int, value: float):
    try:
        data_to_write = bytearray(4)
        set_real(data_to_write, 0, value)
        client.db_write(db_number, start_byte_index, data_to_write)
        return True
    except Exception as e:
        print(f&#34;写入 DB{db_number}.DBD{start_byte_index} 失败: {e}&#34;)
        return False

def read_single_int(client: c.Client, db_number: int, start_byte_index: int):
    try:
        byte_data = client.db_read(db_number, start_byte_index, 2)
        value = get_int(byte_data, 0)
        return value
    except Exception as e:
        print(f&#34;读取 DB{db_number}.DBW{start_byte_index} 失败: {e}&#34;)
        return None

def write_single_int(client: c.Client, db_number: int, start_byte_index: int, value: int):
    try:
        data_to_write = bytearray(2)
        set_int(data_to_write, 0, value)
        client.db_write(db_number, start_byte_index, data_to_write)
        return True
    except Exception as e:
        print(f&#34;写入 DB{db_number}.DBW{start_byte_index} 失败: {e}&#34;)
        return False

def read_string(client: c.Client, db_number: int, start_byte_index: int, max_string_len: int):
    try:
        total_bytes = max_string_len + 2
        byte_data = client.db_read(db_number, start_byte_index, total_bytes)
        value = get_string(byte_data, 0)
        return value
    except Exception as e:
        print(f&#34;读取 DB{db_number}.DBB{start_byte_index} 失败: {e}&#34;)
        return None

def write_string(client: c.Client, db_number: int, start_byte_index: int, value: str, max_string_len: int):
    try:
        total_bytes = max_string_len + 2
        data_to_write = bytearray(total_bytes)
        set_string(data_to_write, 0, value, max_string_len)
        client.db_write(db_number, start_byte_index, data_to_write)
        return True
    except Exception as e:
        print(f&#34;写入 DB{db_number}.DBB{start_byte_index} 失败: {e}&#34;)
        return False

# ----------------------------------------------------
# 步骤 2：主程序 - 连接、执行、断开
# ----------------------------------------------------
def main():
    plc = c.Client()
    try:
        # --- 建立连接 ---
        print(f&#34;正在连接 PLC ({PLC_IP})...&#34;)
        plc.connect(PLC_IP, PLC_RACK, PLC_SLOT)

        if plc.get_connected():
            print(&#34;连接成功！&#34;)

            # --- 1. 读取初始值 ---
            print(&#34;\n--- 1. 正在读取初始值 ---&#34;)
            init_temp = read_single_real(plc, DB_NUM, 4)
            init_count = read_single_int(plc, DB_NUM, 2)
            init_flag = read_single_bool(plc, DB_NUM, 0, 0)
            init_model = read_string(plc, DB_NUM, 10, STRING_MAX_LEN)
            print(f&#34;  初始温度 (DBD4): {init_temp}&#34;)
            print(f&#34;  初始计数 (DBW2): {init_count}&#34;)
            print(f&#34;  初始标志 (DBX0.0): {init_flag}&#34;)
            print(f&#34;  初始型号 (DBB10): {init_model}&#34;)

            # --- 2. 写入新值 ---
            print(&#34;\n--- 2. 正在写入新值 ---&#34;)
            new_temp = round(time.time() % 100, 2) # 用当前时间戳做新值
            new_count = (init_count or 0) + 1
            new_flag = not init_flag
            new_model = f&#34;Test_{int(time.time())}&#34;

            write_single_real(plc, DB_NUM, 4, new_temp)
            write_single_int(plc, DB_NUM, 2, new_count)
            write_single_bool(plc, DB_NUM, 0, 1, new_flag) # 写入 DBX0.1
            write_string(plc, DB_NUM, 10, new_model, STRING_MAX_LEN)
            print(f&#34;  写入温度 -&amp;gt; {new_temp}&#34;)
            print(f&#34;  写入计数 -&amp;gt; {new_count}&#34;)
            print(f&#34;  写入标志 (DBX0.1) -&amp;gt; {new_flag}&#34;)
            print(f&#34;  写入型号 -&amp;gt; {new_model}&#34;)

            # --- 3. 读回写入的值进行验证 ---
            print(&#34;\n--- 3. 正在读回验证 ---&#34;)
            val_temp = read_single_real(plc, DB_NUM, 4)
            val_count = read_single_int(plc, DB_NUM, 2)
            val_flag = read_single_bool(plc, DB_NUM, 0, 1)
            val_model = read_string(plc, DB_NUM, 10, STRING_MAX_LEN)
            print(f&#34;  读回温度 (DBD4): {val_temp} (应为: {new_temp})&#34;)
            print(f&#34;  读回计数 (DBW2): {val_count} (应为: {new_count})&#34;)
            print(f&#34;  读回标志 (DBX0.1): {val_flag} (应为: {new_flag})&#34;)
            print(f&#34;  读回型号 (DBB10): {val_model} (应为: {new_model})&#34;)

            # --- 4. 演示批量读取 (来自步骤 5.1) ---
            print(&#34;\n--- 4. 演示批量读取 (DBB0-DBB9) ---&#34;)
            try:
                # 假设我们想一次性读取 DBX0.0 到 DBB9
                all_data = plc.db_read(DB_NUM, 0, 10) # 读 10 个字节
                val_b_0_0 = get_bool(all_data, 0, 0)
                val_b_0_1 = get_bool(all_data, 0, 1)
                val_i_2 = get_int(all_data, 2)
                val_r_4 = get_real(all_data, 4)
                print(f&#34;  批量读 DBX0.0: {val_b_0_0}&#34;)
                print(f&#34;  批量读 DBX0.1: {val_b_0_1}&#34;)
                print(f&#34;  批量读 DBW2: {val_i_2}&#34;)
                print(f&#34;  批量读 DBD4: {val_r_4}&#34;)
            except Exception as e:
                print(f&#34;  批量读取失败: {e}&#34;)

        else:
            print(&#34;连接失败。请检查 TIA Portal 设置 (PUT/GET) 和网络。&#34;)

    except snap7.snap7exceptions.Snap7Exception as e:
        print(f&#34;连接时发生 Snap7 错误: {e}&#34;)
    except Exception as e:
        print(f&#34;发生未知错误: {e}&#34;)
    finally:
        # --- 断开连接 ---
        if plc.get_connected():
            plc.disconnect()
            print(&#34;\n已断开 PLC 连接。&#34;)

if __name__ == &#34;__main__&#34;:
    main()&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&#34;第-7-步：常见问题-FAQ-与总结&#34;&gt;&lt;a href=&#34;#第-7-步：常见问题-FAQ-与总结&#34; class=&#34;headerlink&#34; title=&#34;第 7 步：常见问题 (FAQ) 与总结&#34;&gt;&lt;/a&gt;第 7 步：常见问题 (FAQ) 与总结&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;我收到了 &lt;code&gt;Snap7Exception: CPU: Item not available&lt;/code&gt; (项目不可用) 错误！&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;90% 的可能&lt;/strong&gt;：你访问的 &lt;strong&gt;DB 块&lt;/strong&gt; 仍然是“&lt;strong&gt;优化的块访问&lt;/strong&gt;”。去 TIA Portal，右键该 DB -&amp;gt; 属性 -&amp;gt; 取消勾选“优化的块访问”，然后重新编译并下载。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;10% 的可能&lt;/strong&gt;：你的地址（DB号、起始字节、长度）写错了。例如，你试图读取 &lt;code&gt;DB1.DBB100&lt;/code&gt;，但 &lt;code&gt;DB1&lt;/code&gt; 只有 50 字节长。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;我收到了 &lt;code&gt;Snap7Exception: ... function refused&lt;/code&gt; (功能被拒绝) 错误！&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;99% 的可能&lt;/strong&gt;：你没有在 TIA Portal 的 CPU 属性中勾选“&lt;strong&gt;允许来自远程伙伴…的 PUT/GET 通信&lt;/strong&gt;”。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;我写入一个 BOOL (DBX0.0)，为什么 DBX0.1 到 DBX0.7 都变成 0 了？&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;你没有使用“&lt;strong&gt;读-改-写&lt;/strong&gt;”模式（见 4.1 节）。你直接用 &lt;code&gt;db_write&lt;/code&gt; 写入了 1 个位，&lt;code&gt;snap7&lt;/code&gt; 必须写入整个字节。你必须先 &lt;code&gt;db_read&lt;/code&gt; 整个字节，在内存中修改那 1 个位，然后再 &lt;code&gt;db_write&lt;/code&gt; 整个字节回去。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;我读取的 STRING 为什么是乱码或者不完整？&lt;/strong&gt;&lt;ul&gt;
&lt;li&gt;你 &lt;code&gt;db_read&lt;/code&gt; 的&lt;strong&gt;长度&lt;/strong&gt;错误。读取 &lt;code&gt;STRING[50]&lt;/code&gt;，你必须 &lt;code&gt;db_read&lt;/code&gt; 52 个字节 (&lt;code&gt;max_len + 2&lt;/code&gt;)。&lt;code&gt;snap7.util.get_string&lt;/code&gt; 需要这 2 个头部字节来正确解析。&lt;/li&gt;
&lt;li&gt;你 &lt;code&gt;write_string&lt;/code&gt; 的&lt;strong&gt;最大长度&lt;/strong&gt;参数错误。&lt;code&gt;set_string&lt;/code&gt; 需要知道 &lt;code&gt;max_string_len&lt;/code&gt; 才能正确生成头部。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;

 &lt;h1 id=&#34;🕓-Python-datetime-模块详细教程（含雷点总结）&#34;&gt;&lt;a href=&#34;#🕓-Python-datetime-模块详细教程（含雷点总结）&#34; class=&#34;headerlink&#34; title=&#34;🕓 Python datetime 模块详细教程（含雷点总结）&#34;&gt;&lt;/a&gt;🕓 Python &lt;code&gt;datetime&lt;/code&gt; 模块详细教程（含雷点总结）&lt;/h1&gt;&lt;hr&gt;
&lt;h2 id=&#34;一、datetime-模块概述&#34;&gt;&lt;a href=&#34;#一、datetime-模块概述&#34; class=&#34;headerlink&#34; title=&#34;一、datetime 模块概述&#34;&gt;&lt;/a&gt;一、&lt;code&gt;datetime&lt;/code&gt; 模块概述&lt;/h2&gt;&lt;p&gt;&lt;code&gt;datetime&lt;/code&gt; 是 Python 用于处理日期、时间、时间差、时区等操作的标准库。&lt;/p&gt;
&lt;p&gt;主要包含 6 个核心类：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;类名&lt;/th&gt;
&lt;th&gt;作用&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;datetime.date&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;表示日期（年、月、日）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;datetime.time&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;表示时间（时、分、秒、微秒）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;datetime.datetime&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;同时表示日期 + 时间&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;datetime.timedelta&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;表示时间差&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;datetime.tzinfo&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;表示时区信息（基类）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;datetime.timezone&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;具体的时区类&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;二、模块导入方式（⚠️第一个雷点）&#34;&gt;&lt;a href=&#34;#二、模块导入方式（⚠️第一个雷点）&#34; class=&#34;headerlink&#34; title=&#34;二、模块导入方式（⚠️第一个雷点）&#34;&gt;&lt;/a&gt;二、模块导入方式（⚠️第一个雷点）&lt;/h2&gt;&lt;p&gt;有两种常见导入方式，&lt;strong&gt;推荐第二种&lt;/strong&gt;：&lt;/p&gt;
&lt;h3 id=&#34;❌-错误或容易踩坑写法：&#34;&gt;&lt;a href=&#34;#❌-错误或容易踩坑写法：&#34; class=&#34;headerlink&#34; title=&#34;❌ 错误或容易踩坑写法：&#34;&gt;&lt;/a&gt;❌ 错误或容易踩坑写法：&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime

now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# ❌ 会报错：module &#39;datetime&#39; has no attribute &#39;now&#39;&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;blockquote&gt;
&lt;p&gt;因为 &lt;code&gt;datetime&lt;/code&gt; 是模块名，而 &lt;code&gt;datetime.now()&lt;/code&gt; 属于类 &lt;code&gt;datetime.datetime&lt;/code&gt;。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;✅-正确写法：&#34;&gt;&lt;a href=&#34;#✅-正确写法：&#34; class=&#34;headerlink&#34; title=&#34;✅ 正确写法：&#34;&gt;&lt;/a&gt;✅ 正确写法：&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime
now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;或者：&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime
now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;⚠️ &lt;strong&gt;总结：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;datetime&lt;/code&gt; 是模块；&lt;/li&gt;
&lt;li&gt;&lt;code&gt;datetime.datetime&lt;/code&gt; 是类；&lt;/li&gt;
&lt;li&gt;所以必须是 &lt;code&gt;datetime.datetime.now()&lt;/code&gt; 或者直接导入类。&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;三、获取当前时间与日期&#34;&gt;&lt;a href=&#34;#三、获取当前时间与日期&#34; class=&#34;headerlink&#34; title=&#34;三、获取当前时间与日期&#34;&gt;&lt;/a&gt;三、获取当前时间与日期&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; date&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; time

&lt;span class=&#34;token comment&#34;&gt;# 当前日期时间&lt;/span&gt;
now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 2025-10-17 11:30:05.234567&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# 当前日期&lt;/span&gt;
today &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; date&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;today&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;today&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 2025-10-17&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# 当前时间&lt;/span&gt;
t &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;time&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;t&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 11:30:05.234567&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;四、创建自定义日期时间对象&#34;&gt;&lt;a href=&#34;#四、创建自定义日期时间对象&#34; class=&#34;headerlink&#34; title=&#34;四、创建自定义日期时间对象&#34;&gt;&lt;/a&gt;四、创建自定义日期时间对象&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; date&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; time

&lt;span class=&#34;token comment&#34;&gt;# 日期对象&lt;/span&gt;
d &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; date&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2025&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;17&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;d&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;year&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; d&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;month&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; d&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;day&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 2025 10 17&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# 时间对象&lt;/span&gt;
t &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; time&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;14&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;30&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;45&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;t&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;hour&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; t&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;minute&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; t&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;second&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 14 30 45&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# 日期+时间&lt;/span&gt;
dt &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2025&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;17&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;14&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;30&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;45&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;dt&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 2025-10-17 14:30:45&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;五、日期与字符串互转&#34;&gt;&lt;a href=&#34;#五、日期与字符串互转&#34; class=&#34;headerlink&#34; title=&#34;五、日期与字符串互转&#34;&gt;&lt;/a&gt;五、日期与字符串互转&lt;/h2&gt;&lt;h3 id=&#34;✅-格式化输出（strftime）&#34;&gt;&lt;a href=&#34;#✅-格式化输出（strftime）&#34; class=&#34;headerlink&#34; title=&#34;✅ 格式化输出（strftime）&#34;&gt;&lt;/a&gt;✅ 格式化输出（&lt;code&gt;strftime&lt;/code&gt;）&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime
now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;strftime&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;%Y-%m-%d %H:%M:%S&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 2025-10-17 11:30:05&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;strftime&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;%A, %B %d, %Y&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;      &lt;span class=&#34;token comment&#34;&gt;# Friday, October 17, 2025&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;常用格式说明：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;占位符&lt;/th&gt;
&lt;th&gt;含义&lt;/th&gt;
&lt;th&gt;示例&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%Y&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;四位年份&lt;/td&gt;
&lt;td&gt;2025&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%m&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;月（两位）&lt;/td&gt;
&lt;td&gt;10&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%d&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;日（两位）&lt;/td&gt;
&lt;td&gt;17&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%H&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;时（24小时制）&lt;/td&gt;
&lt;td&gt;14&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%M&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;分&lt;/td&gt;
&lt;td&gt;30&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%S&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;秒&lt;/td&gt;
&lt;td&gt;45&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;%A&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;星期名&lt;/td&gt;
&lt;td&gt;Friday&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h3 id=&#34;✅-字符串解析为日期对象（strptime）&#34;&gt;&lt;a href=&#34;#✅-字符串解析为日期对象（strptime）&#34; class=&#34;headerlink&#34; title=&#34;✅ 字符串解析为日期对象（strptime）&#34;&gt;&lt;/a&gt;✅ 字符串解析为日期对象（&lt;code&gt;strptime&lt;/code&gt;）&lt;/h3&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime

dt_str &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;2025-10-17 11:35:00&#34;&lt;/span&gt;
dt &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;strptime&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;dt_str&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;%Y-%m-%d %H:%M:%S&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;dt&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# datetime(2025, 10, 17, 11, 35, 0)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;⚠️ &lt;strong&gt;雷点：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;格式必须完全匹配，否则报错 &lt;code&gt;ValueError: time data &#39;xxx&#39; does not match format&lt;/code&gt;。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;%m&lt;/code&gt; 必须是两位（01&lt;del&gt;12），不能是 1&lt;/del&gt;12。&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;六、时间计算（timedelta）&#34;&gt;&lt;a href=&#34;#六、时间计算（timedelta）&#34; class=&#34;headerlink&#34; title=&#34;六、时间计算（timedelta）&#34;&gt;&lt;/a&gt;六、时间计算（&lt;code&gt;timedelta&lt;/code&gt;）&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; timedelta

now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# 加减天数&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;now &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt; timedelta&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;days&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 明天&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;now &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt; timedelta&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;days&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;7&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 一周前&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# 加减小时/分钟&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;now &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt; timedelta&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;hours&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;now &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt; timedelta&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;minutes&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;30&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;⚠️ &lt;strong&gt;雷点：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;timedelta&lt;/code&gt; 的参数是关键字参数：&lt;code&gt;days=&lt;/code&gt;, &lt;code&gt;hours=&lt;/code&gt;, &lt;code&gt;minutes=&lt;/code&gt;，不要直接传位置参数。&lt;/li&gt;
&lt;li&gt;微秒（&lt;code&gt;microseconds&lt;/code&gt;）容易被忽略，调试日志时可用 &lt;code&gt;strftime(&#34;%f&#34;)&lt;/code&gt; 查看。&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;七、比较时间&#34;&gt;&lt;a href=&#34;#七、比较时间&#34; class=&#34;headerlink&#34; title=&#34;七、比较时间&#34;&gt;&lt;/a&gt;七、比较时间&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime

t1 &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2025&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;17&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
t2 &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2025&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;17&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;12&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;t1 &lt;span class=&#34;token operator&#34;&gt;&amp;lt;&lt;/span&gt; t2&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# True&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;t2 &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt; t1&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 2:00:00&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;八、获取时间戳（Unix-时间）&#34;&gt;&lt;a href=&#34;#八、获取时间戳（Unix-时间）&#34; class=&#34;headerlink&#34; title=&#34;八、获取时间戳（Unix 时间）&#34;&gt;&lt;/a&gt;八、获取时间戳（Unix 时间）&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime

now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
timestamp &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;timestamp&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;timestamp&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 例如 1760643050.123456&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# 时间戳 → datetime&lt;/span&gt;
dt &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;fromtimestamp&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;timestamp&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;dt&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;⚠️ &lt;strong&gt;雷点：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;timestamp()&lt;/code&gt; 默认基于本地时区；&lt;/li&gt;
&lt;li&gt;若需要 UTC 时间，请使用 &lt;code&gt;datetime.utcnow()&lt;/code&gt; 或 &lt;code&gt;.astimezone()&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;九、时区处理（timezone）&#34;&gt;&lt;a href=&#34;#九、时区处理（timezone）&#34; class=&#34;headerlink&#34; title=&#34;九、时区处理（timezone）&#34;&gt;&lt;/a&gt;九、时区处理（timezone）&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; timezone&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; timedelta

&lt;span class=&#34;token comment&#34;&gt;# 设置东八区（中国标准时间）&lt;/span&gt;
tz &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; timezone&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;timedelta&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;hours&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;8&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# 当前UTC时间&lt;/span&gt;
utc_now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;timezone&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;utc&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;utc_now&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# 转为北京时间&lt;/span&gt;
bj_time &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; utc_now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;astimezone&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;tz&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;bj_time&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;⚠️ &lt;strong&gt;雷点：&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;datetime.now()&lt;/code&gt; 默认“&lt;strong&gt;无时区（naive datetime）&lt;/strong&gt;”，不能直接与带时区的时间比较；&lt;/li&gt;
&lt;li&gt;混用会报 &lt;code&gt;TypeError: can&#39;t compare offset-naive and offset-aware datetimes&lt;/code&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;h2 id=&#34;十、提取时间部分属性&#34;&gt;&lt;a href=&#34;#十、提取时间部分属性&#34; class=&#34;headerlink&#34; title=&#34;十、提取时间部分属性&#34;&gt;&lt;/a&gt;十、提取时间部分属性&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime

now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;year&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;month&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;day&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;hour&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;minute&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;second&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;weekday&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 星期几（0=周一）&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;十一、实战案例：判断当前时间阶段&#34;&gt;&lt;a href=&#34;#十一、实战案例：判断当前时间阶段&#34; class=&#34;headerlink&#34; title=&#34;十一、实战案例：判断当前时间阶段&#34;&gt;&lt;/a&gt;十一、实战案例：判断当前时间阶段&lt;/h2&gt;&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; time

&lt;span class=&#34;token keyword&#34;&gt;def&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;get_time_period&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
    now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;time&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

    MORNING_START &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; time&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;6&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    NOON_START &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; time&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;13&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;30&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    EVENING_START &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; time&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;20&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;30&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
    NIGHT_END &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; time&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;3&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;30&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

    &lt;span class=&#34;token keyword&#34;&gt;if&lt;/span&gt; now &lt;span class=&#34;token operator&#34;&gt;&amp;gt;=&lt;/span&gt; EVENING_START &lt;span class=&#34;token keyword&#34;&gt;or&lt;/span&gt; now &lt;span class=&#34;token operator&#34;&gt;&amp;lt;=&lt;/span&gt; NIGHT_END&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;晚上&#34;&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;elif&lt;/span&gt; MORNING_START &lt;span class=&#34;token operator&#34;&gt;&amp;lt;=&lt;/span&gt; now &lt;span class=&#34;token operator&#34;&gt;&amp;lt;&lt;/span&gt; NOON_START&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;早上&#34;&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;elif&lt;/span&gt; NOON_START &lt;span class=&#34;token operator&#34;&gt;&amp;lt;=&lt;/span&gt; now &lt;span class=&#34;token operator&#34;&gt;&amp;lt;&lt;/span&gt; EVENING_START&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;中午&#34;&lt;/span&gt;
    &lt;span class=&#34;token keyword&#34;&gt;else&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;:&lt;/span&gt;
        &lt;span class=&#34;token keyword&#34;&gt;return&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;凌晨&#34;&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;get_time_period&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;hr&gt;
&lt;h2 id=&#34;十二、常见雷区总结-⚡&#34;&gt;&lt;a href=&#34;#十二、常见雷区总结-⚡&#34; class=&#34;headerlink&#34; title=&#34;十二、常见雷区总结 ⚡&#34;&gt;&lt;/a&gt;十二、常见雷区总结 ⚡&lt;/h2&gt;&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;雷区&lt;/th&gt;
&lt;th&gt;错误写法&lt;/th&gt;
&lt;th&gt;正确写法&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;模块与类混用&lt;/td&gt;
&lt;td&gt;&lt;code&gt;datetime.now()&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;datetime.datetime.now()&lt;/code&gt; 或 &lt;code&gt;from datetime import datetime&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;构造时间对象&lt;/td&gt;
&lt;td&gt;&lt;code&gt;datetime.datetime.time(6, 0)&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;time(6, 0)&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;code&gt;strftime&lt;/code&gt; 格式错误&lt;/td&gt;
&lt;td&gt;&lt;code&gt;%y-%m-%d&lt;/code&gt; (小写 y)&lt;/td&gt;
&lt;td&gt;&lt;code&gt;%Y-%m-%d&lt;/code&gt; (大写 Y)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;时区比较&lt;/td&gt;
&lt;td&gt;直接比较 naive 与 aware&lt;/td&gt;
&lt;td&gt;先用 &lt;code&gt;.astimezone()&lt;/code&gt; 统一&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;字符串解析&lt;/td&gt;
&lt;td&gt;格式不匹配时报错&lt;/td&gt;
&lt;td&gt;用正确的 &lt;code&gt;%Y-%m-%d %H:%M:%S&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;时间计算&lt;/td&gt;
&lt;td&gt;&lt;code&gt;datetime + 3&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;&lt;code&gt;datetime + timedelta(days=3)&lt;/code&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;hr&gt;
&lt;h2 id=&#34;十三、总结：使用建议-🧭&#34;&gt;&lt;a href=&#34;#十三、总结：使用建议-🧭&#34; class=&#34;headerlink&#34; title=&#34;十三、总结：使用建议 🧭&#34;&gt;&lt;/a&gt;十三、总结：使用建议 🧭&lt;/h2&gt;&lt;p&gt;✅ &lt;strong&gt;推荐导入方式：&lt;/strong&gt;&lt;/p&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; date&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; time&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; timedelta&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; timezone&lt;span aria-hidden=&#34;true&#34; class=&#34;line-numbers-rows&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;p&gt;✅ &lt;strong&gt;推荐实践顺序：&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;使用 &lt;code&gt;datetime.now()&lt;/code&gt; 获取当前时间；&lt;/li&gt;
&lt;li&gt;使用 &lt;code&gt;strftime()&lt;/code&gt; 格式化输出；&lt;/li&gt;
&lt;li&gt;使用 &lt;code&gt;strptime()&lt;/code&gt; 从字符串解析；&lt;/li&gt;
&lt;li&gt;使用 &lt;code&gt;timedelta&lt;/code&gt; 做加减；&lt;/li&gt;
&lt;li&gt;使用 &lt;code&gt;timezone&lt;/code&gt; 管理时区；&lt;/li&gt;
&lt;li&gt;避免直接混用模块名 &lt;code&gt;datetime&lt;/code&gt; 和类名 &lt;code&gt;datetime&lt;/code&gt;。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;下面是一份 &lt;strong&gt;完整可执行的 Python 脚本&lt;/strong&gt;，展示了 &lt;code&gt;datetime&lt;/code&gt; 模块的全部常用功能、典型实战用法以及常见雷点说明。&lt;/p&gt;
&lt;p&gt;你可以直接保存为：&lt;br&gt; 📄 &lt;strong&gt;&lt;code&gt;datetime_demo.py&lt;/code&gt;&lt;/strong&gt;&lt;br&gt; 然后在任何 Python 环境中运行（包括 Anaconda、VSCode、PyCharm、命令行等）。&lt;/p&gt;
&lt;hr&gt;
&lt;pre class=&#34;line-numbers language-python&#34; data-language=&#34;python&#34;&gt;&lt;code class=&#34;language-python&#34;&gt;&lt;span class=&#34;token comment&#34;&gt;# ==========================================&lt;/span&gt;
&lt;span class=&#34;token comment&#34;&gt;# datetime 模块完整示例脚本&lt;/span&gt;
&lt;span class=&#34;token comment&#34;&gt;# 功能: 演示 datetime 的全部主要用法 + 雷点说明&lt;/span&gt;
&lt;span class=&#34;token comment&#34;&gt;# ==========================================&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;from&lt;/span&gt; datetime &lt;span class=&#34;token keyword&#34;&gt;import&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; date&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; time&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; timedelta&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; timezone

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;=&#34;&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;80&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;1️⃣  获取当前时间、日期、时间戳&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;=&#34;&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;80&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

now &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;now&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;  &lt;span class=&#34;token comment&#34;&gt;# 当前时间（本地）&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;当前时间：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; now&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;当前日期：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; date&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;today&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;当前时间部分：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;time&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;当前时间戳（秒）：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;timestamp&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;\n&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# --------------------------------------------------------------------------------&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;=&#34;&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;80&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;2️⃣  创建自定义日期与时间对象&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;=&#34;&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;80&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

d &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; date&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2025&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;17&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
t &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; time&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;14&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;30&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;45&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
dt &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2025&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;17&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;14&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;30&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;45&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;日期对象：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; d&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;时间对象：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; t&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;完整日期时间对象：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; dt&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;\n&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# --------------------------------------------------------------------------------&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;=&#34;&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;80&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;3️⃣  日期 ↔ 字符串互转 (strftime / strptime)&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;=&#34;&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;80&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

formatted &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; now&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;strftime&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;%Y-%m-%d %H:%M:%S&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;格式化输出：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; formatted&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

parsed &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; datetime&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;strptime&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;2025-10-17 14:35:00&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;%Y-%m-%d %H:%M:%S&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;字符串解析为 datetime 对象：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; parsed&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;\n&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token comment&#34;&gt;# --------------------------------------------------------------------------------&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;=&#34;&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;80&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;4️⃣  时间加减与时间差 (timedelta)&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;=&#34;&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;*&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;80&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

tomorrow &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; now &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt; timedelta&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;days&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
last_week &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; now &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt; timedelta&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;days&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;7&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
after_3_hours &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; now &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt; timedelta&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;hours&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;3&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
before_15_min &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; now &lt;span class=&#34;token operator&#34;&gt;-&lt;/span&gt; timedelta&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;minutes&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;15&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;

&lt;span class=&#34;token keyword&#34;&gt;print&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;明天：&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; tomorrow&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;
